args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-26-augur-example');S<-file.path(P,'biofigure');.libPaths(c(file.path(W,'Rlib'),.libPaths()));suppressPackageStartupMessages({library(dplyr);library(tidyr);library(ggplot2);library(ComplexHeatmap);library(grid)})
source(file.path(S,'scripts/figure_style.R'));source(file.path(S,'benchmark/library/single-cell/augur-2021/sources/author-code/R/plot_lollipop.R'))
wr<-function(x,p)jsonlite::write_json(x,p,pretty=TRUE,auto_unbox=TRUE,digits=NA)
ct<-c('CellTypeA','CellTypeB','CellTypeC');pal<-bf_palette('tol-bright-7',kind='categorical',levels=ct,skill_root=S);all<-lapply(c(10,20,40),function(n)readRDS(file.path(W,paste0('native-size',n,'.rds'))));names(all)<-c('10','20','40')
cv<-bind_rows(lapply(names(all),function(n)mutate(all[[n]]$results,subsample_size=as.integer(n))));auc_rows<-filter(cv,metric=='roc_auc');stopifnot(!anyNA(auc_rows$estimate),all(auc_rows$estimate>=0 & auc_rows$estimate<=1))
sub<-auc_rows%>%group_by(cell_type,subsample_size,subsample_idx)%>%summarise(auc=mean(estimate),.groups='drop');summary<-sub%>%group_by(cell_type,subsample_size)%>%summarise(mean_auc=mean(auc),sd_auc=sd(auc),subsamples=n(),.groups='drop')
for(n in names(all)){reference<-all[[n]]$AUC;computed<-filter(summary,subsample_size==as.integer(n));stopifnot(max(abs(reference$auc-computed$mean_auc[match(reference$cell_type,computed$cell_type)]))<1e-12)}
importance<-all[['20']]$feature_importance%>%group_by(cell_type,gene)%>%summarise(mean_importance=mean(importance),models=n(),.groups='drop');top<-importance%>%group_by(cell_type)%>%slice_max(mean_importance,n=5,with_ties=FALSE)%>%ungroup();genes<-unique(top$gene);shown<-filter(importance,gene%in%genes)%>%complete(gene=genes,cell_type=ct)
mat<-matrix(NA_real_,nrow=length(genes),ncol=3,dimnames=list(genes,ct));for(i in seq_len(nrow(shown)))mat[shown$gene[i],shown$cell_type[i]]<-shown$mean_importance[i]
# One shared order from maximum importance, no independent per-column clustering.
mat<-mat[order(apply(mat,1,max,na.rm=TRUE),decreasing=TRUE),,drop=FALSE]
write.csv(summary,file.path(P,'results/plot_data/augur_example_20261026_robustness.csv'),row.names=FALSE);write.csv(sub,file.path(P,'results/plot_data/augur_example_20261026_subsamples.csv'),row.names=FALSE);write.csv(data.frame(gene=rownames(mat),mat,check.names=FALSE),file.path(P,'results/plot_data/augur_example_20261026_importance.csv'),row.names=FALSE);write.csv(importance,file.path(P,'results/plot_data/augur_example_20261026_all_importance.csv'),row.names=FALSE)
# Retain the author's native lollipop function, adapt only semantic color and font/layout.
pa<-plot_lollipop(all[['20']]);pa$layers[[2]]$mapping<-aes(colour=cell_type);pa$layers[[4]]$mapping<-aes(xend=cell_type,yend=.5,colour=cell_type);for(i in seq_along(pa$layers))if(inherits(pa$layers[[i]]$geom,'GeomText')){pa$layers[[i]]$aes_params$family<-'Arial';pa$layers[[i]]$aes_params$size<-2.4}
th<-theme_classic(base_family='Arial',base_size=7)+theme(axis.text=element_text(size=6.5,colour='#30343B'),axis.title=element_text(size=7),axis.line=element_line(colour='#30343B',linewidth=.25),axis.ticks=element_line(linewidth=.2),legend.text=element_text(size=6.5),legend.title=element_blank(),plot.margin=margin(3,5,3,3),panel.grid=element_blank())
pa<-pa+labs(x=NULL)+scale_colour_manual(values=pal,guide='none')+scale_y_continuous('AUC',limits=c(.45,1.02),breaks=c(.5,.75,1))+th
pb<-ggplot(summary,aes(subsample_size,mean_auc,colour=cell_type,group=cell_type))+geom_hline(yintercept=.5,linetype='dotted',linewidth=.25,colour='#727B82')+geom_errorbar(aes(ymin=pmax(0,mean_auc-sd_auc),ymax=pmin(1,mean_auc+sd_auc)),width=1.5,linewidth=.3)+geom_line(linewidth=.45)+geom_point(size=1.7)+scale_colour_manual(values=pal)+scale_x_continuous('Cells per condition',breaks=c(10,20,40))+scale_y_continuous('AUC (mean ± SD)',limits=c(.25,1.02),breaks=c(.25,.5,.75,1))+th+theme(legend.position='bottom',legend.margin=margin(0,0,0,0),legend.key.width=unit(3,'mm'),legend.spacing.x=unit(1,'mm'))+guides(colour=guide_legend(nrow=1))
limit<-signif(max(abs(mat),na.rm=TRUE)*1.05,2)
saveRDS(list(a=pa,b=pb,importance=mat,palette=pal,limit=limit),file.path(W,'plot-inputs.rds'))
qc<-jsonlite::fromJSON(file.path(W,'input-qc.json'));qc$matrix_rows<-nrow(mat);qc$matrix_columns<-ncol(mat);qc$cell_mm<-4;qc$subsample_sizes<-c(10,20,40);qc$subsamples_per_size<-20;qc$folds<-3;qc$trees<-100;qc$native_auc_means_match_csv<-TRUE;qc$all_auc_finite<-TRUE;qc$non_auc_missing_metrics<-sum(is.na(cv$estimate));qc$importance_na_cells<-sum(is.na(mat));qc$importance_scope<-'MeanDecreaseAccuracy averaged over folds/subsamples in which a feature was selected; NA is not silently filled with zero.';wr(qc,file.path(W,'input-qc.json'))
# Exploratory preview; formal rendering follows the current CP2 contract.
source_file<-file.path(W,'draw_panels.R');source(source_file);ragg::agg_png(file.path(W,'exploratory.png'),width=136,height=110,units='mm',res=200,background='white');draw_panels(readRDS(file.path(W,'plot-inputs.rds')),file.path(W,'exploratory-layout.json'));dev.off()
